SELECT p.id AS position_id, s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.signal_mode, s.decision, s.original_decision, s.confidence_score, s.data_quality_valid, s.final_entry_allowed FROM paper_position p JOIN trade_signal s ON s.symbol = p.symbol AND s.interval_code IN ('5m','1h') AND s.generated_at BETWEEN p.opened_at - INTERVAL 3 HOUR AND p.closed_at + INTERVAL 1 MINUTE WHERE p.id IN (104,101,96,91,82,78) ORDER BY p.id, s.interval_code, s.generated_at